modal.addEventListener('submit',e=>{e.preventDefault();const form=e.target,kind=form.dataset.form;try{if(['save-day','new-application','reconsider','reject','coordinate','reschedule','researcher','researcher-email','reset'].includes(kind)&&!isAdmin())throw Error('這項操作只提供管理者使用。');if(kind==='save-day')saveDay(form);else if(kind==='save-my-day')saveMyDay(form);else if(kind==='new-application')newApplication(form);else if(kind==='researcher-confirm')confirmResearcherForm(form);else if(kind==='researcher-decline')researcherDecline(form);else if(kind==='reconsider')requestReconsider(form);else if(kind==='reject')rejectApplication(form);else if(kind==='coordinate')coordinate(form);else if(kind==='reschedule')reschedule(form);else if(kind==='session')saveSession(form);else if(kind==='overall-note')saveOverallNote(form);else if(kind==='researcher')addResearcher(form);else if(kind==='researcher-email')saveResearcherEmail(form);else if(kind==='reset'){state=seedState();ui.actor='r1';ui.view='availability';ui.filter='all';ui.month=monthKey(today);ui.day=firstWorkday;save()}closeModal();notify('已更新虛構測試資料。')}catch(err){notify(err.message||'操作無法完成')}});
root.addEventListener('submit',e=>{const form=e.target,kind=form.dataset.form;if(!['target','mail-settings'].includes(kind))return;e.preventDefault();if(!isAdmin())return notify('只有管理者能調整此設定。');const data=new FormData(form);if(kind==='target'){state.target=Number(data.get('target'));audit('更新目標',`目標改為 ${state.target}`);save();notify('目標已更新。')}else{state.mailSettings.monthlyAvailabilityReminderEnabled=data.has('monthlyEnabled');state.mailSettings.reminderDay=Number(data.get('reminderDay'))||1;audit('更新排班提醒',`${state.mailSettings.monthlyAvailabilityReminderEnabled?'啟用':'停用'} · 每月 ${state.mailSettings.reminderDay} 日 09:00`);save();if(state.mailSettings.monthlyAvailabilityReminderEnabled&&today.getDate()>=state.mailSettings.reminderDay)runDueMonthlyReminder();else notify('排班提醒設定已保存；測試版不會在背景執行。')}});

window.addEventListener('storage',e=>{if(e.key!==STORE_KEY)return;const latest=latestStoredState();if(!latest)return;state=latest;if(modal.open){externalStateChanged=true;notify('其他分頁已更新資料；關閉此視窗後，畫面會重新整理。')}else render()});

function saveDay(form){const date=String(new FormData(form).get('date'));refreshDayBeforeSave(form,date);const closed=!!form.querySelector('[name=closed]').checked,existing=state.slots.filter(s=>s.date===date),rows=[...form.querySelectorAll('.slot-edit')].map(row=>{const assigned=row.querySelector('.assignee').value;if(assigned==='__conflict__')throw Error(`${row.querySelector('.start').value}–${row.querySelector('.end').value} 仍有重複指派，請先選定一位研究者。`);return {id:row.dataset.slotId||id('slot'),date,start:row.querySelector('.start').value,end:row.querySelector('.end').value,researcherIds:assigned?[assigned]:[],source:row.dataset.slotId?'edited':'custom'}}).sort((a,b)=>a.start.localeCompare(b.start));for(const row of rows){if(!row.start||!row.end||minutes(row.end)<=minutes(row.start))throw Error('每個時段都需要正確的起訖時間。');if(minutes(row.start)<0||minutes(row.end)>1440)throw Error('時間超出當日範圍。')}for(let i=1;i<rows.length;i++)if(minutes(rows[i].start)-minutes(rows[i-1].end)<30)throw Error(`${rows[i-1].end} 與 ${rows[i].start} 之間不足 30 分鐘緩衝。`);for(const old of existing){if(!occupant(old))continue;const next=rows.find(r=>r.id===old.id);if(!next||next.start!==old.start||next.end!==old.end||closed)throw Error('已有報名者的時段不能直接修改或關閉，請使用改期。')}state.slots=state.slots.filter(s=>s.date!==date).concat(rows);state.closedDates=state.closedDates.filter(x=>x!==date);if(closed)state.closedDates.push(date);audit('更新整日排班',`${date}，${rows.length} 個時段${closed?'，不開放':''}`);save()}
function saveMyDay(form){if(isAdmin())throw Error('請先切換到研究者視角。');const data=new FormData(form),date=String(data.get('date'));refreshDayBeforeSave(form,date);const start=String(data.get('customStart')||''),end=String(data.get('customEnd')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||isDayClosed(date))throw Error('此日期無法編輯。');if(!!start!==!!end)throw Error('新增彈性時段需要開始與結束時間。');const existing=state.slots.filter(s=>s.date===date);if(existing.some(hasDuplicateAssignees))throw Error('這天有舊的重複指派，請管理者先修正後再儲存。');const selected=new Set([...form.querySelectorAll('[data-my-slot]:checked')].map(x=>x.dataset.mySlot));const planned=existing.map(slot=>{const owners=slot.researcherIds||[],owner=owners[0]||null;if(occupant(slot))return {...slot,researcherIds:[...owners]};if(selected.has(slot.id)){if(owner&&owner!==ui.actor)throw Error(`${slot.start}–${slot.end} 已由 ${scheduleName(owner)} 填寫，請選其他時段。`);return {...slot,researcherIds:[ui.actor]}}return {...slot,researcherIds:owner===ui.actor?[]:[...owners]}});let removed=[];if(start){if(minutes(end)<=minutes(start))throw Error('結束時間必須晚於開始時間。');for(const slot of planned){const tooClose=minutes(start)<minutes(slot.end)+30&&minutes(slot.start)<minutes(end)+30;if(!tooClose)continue;if(slot.researcherIds.length||occupant(slot))throw Error(`${start}–${end} 與已安排的 ${slot.start}–${slot.end} 重疊或未留 30 分鐘緩衝，無法儲存。`);removed.push(slot.id)}}const assigned=planned.filter(slot=>slot.researcherIds.length).sort((a,b)=>a.start.localeCompare(b.start));for(let i=1;i<assigned.length;i++)if(minutes(assigned[i].start)-minutes(assigned[i-1].end)<30)throw Error(`${assigned[i-1].start}–${assigned[i-1].end} 已有人填寫，與 ${assigned[i].start}–${assigned[i].end} 未留足 30 分鐘緩衝。`);
  const removedIds=new Set(removed);state.slots=state.slots.filter(s=>s.date!==date).concat(planned.filter(s=>!removedIds.has(s.id)));if(start)state.slots.push({id:id('slot'),date,start,end,researcherIds:[ui.actor],source:'custom'});audit('更新我的排班',`${date} · ${actorName()}`);save()}
function newApplication(form){
  const latest=latestStoredState();if(latest)state=latest;
  const data=new FormData(form),slot=state.slots.find(s=>s.id===data.get('slotId'));
  if(!slot||!isSimulatable(slot)||activeBookings().some(a=>a.slotId===slot.id))throw Error('此時段已無法選擇，請重新挑選。每個時段只能保留一位受試者。');
  const a={id:id('app'),code:id('case'),name:String(data.get('name')).trim(),age:Number(data.get('age')),student:data.has('student'),taiwanNational:data.has('taiwanNational'),idCheck:data.has('idCheck'),prior:data.has('prior'),blacklisted:data.has('blacklisted'),blacklistReason:'',email:`${id('demo')}@example.invalid`,slotId:slot.id,status:'review',assignedResearcherId:null,declinedResearcherIds:[],declineHistory:[],reconsiderationRequests:[],attendance:null,resultRequested:false,participantNote:'',createdAt:new Date().toISOString()};
  if(!a.name)throw Error('請輸入虛構受試者姓名。');
  state.applications.push(a);mail('報名收件確認',a.email,`${a.name} · 已收到報名，待審核與研究者確認`,{appId:a.id,recipientName:a.name});
  const flags=flagText(a);if(flags.length){mail('報名需審核','管理者測試信箱',`${a.name}：${flags.join('、')}`,{appId:a.id,templateVars:{flags:flags.join('、')}});audit('待管理者審核',`${a.name} · ${flags.join('、')}`)}else{assignNextResearcher(a);audit('自動初查通過',`${a.name} → 研究者確認`)}save()
}
function sendResearcherConfirmation(a,rid,kind='研究者確認邀請',message=''){
  const r=researcher(rid),s=slotOf(a);if(!r||!s)return;
  a.researcherConfirmationToken=id('confirm');
  const actionUrl=localActionUrl({confirm:a.id,researcher:rid,key:a.researcherConfirmationToken});
  mail(kind,r.email,`${a.name} · ${slotLabel(s)}，請確認是否可執行`,{appId:a.id,researcherId:rid,recipientName:r.name,linkType:'confirmation',actionUrl,templateVars:{managerMessage:message}});
}
function assignNextResearcher(a){
  const s=slotOf(a);if(s&&hasDuplicateAssignees(s)){a.assignedResearcherId=null;a.coordinationAssignment=false;a.status='needs_coordination';mail('排班重複需處理','管理者測試信箱',`${a.name} · ${slotLabel(s)} 有多位研究者填寫，請先修正為一位`,{appId:a.id});return}
  const next=s?.researcherIds[0]&&!a.declinedResearcherIds.includes(s.researcherIds[0])?s.researcherIds[0]:null;a.coordinationAssignment=false;
  if(next){a.assignedResearcherId=next;a.status='researcher_pending';sendResearcherConfirmation(a,next)}
  else{a.assignedResearcherId=null;a.status='needs_coordination';mail('需協調研究者','管理者測試信箱',`${a.name} · ${slotLabel(s)} 無可支援研究者`,{appId:a.id})}
}
function adminApprove(a){if(a.status!=='review')return;assignNextResearcher(a);audit('審核通過',a.name);save();notify('已送研究者確認；尚未寄錄取信。')}
function confirmResearcherForm(form){const data=new FormData(form),a=state.applications.find(x=>x.id===data.get('appId'));if(!a||a.status!=='researcher_pending'||a.assignedResearcherId!==ui.actor)throw Error('這筆場次目前沒有分派給此研究者。');if(!data.has('canRun'))throw Error('請先確認此時段可執行。');researcherConfirm(a)}
function researcherConfirm(a){if(a.status!=='researcher_pending'||a.assignedResearcherId!==ui.actor)throw Error('這筆場次目前沒有分派給此研究者。');const s=slotOf(a);if(!s||hasDuplicateAssignees(s)||(!a.coordinationAssignment&&!(s.researcherIds.length===1&&s.researcherIds[0]===a.assignedResearcherId)))throw Error('這個時段尚未確認為單一研究者，請管理者先修正排班。');a.status='confirmed';let evt=state.calendarEvents.find(x=>x.appId===a.id);if(evt){evt.slotId=s.id;evt.researcherId=a.assignedResearcherId;evt.syncStatus='pending'}else state.calendarEvents.push({id:id('cal'),appId:a.id,slotId:s.id,researcherId:a.assignedResearcherId,syncStatus:'pending',createdAt:new Date().toISOString()});const r=researcher(a.assignedResearcherId);mail('錄取通知',a.email,`${a.name} · ${slotLabel(s)} 已確認；附實驗地點與說明`,{appId:a.id,recipientName:a.name});mail('實驗前提醒（預定）',a.email,`${a.name} · ${slotLabel(s)} 實驗前提醒`,{appId:a.id,recipientName:a.name,scheduledFor:addDays(s.date,-1)});audit('研究者確認',`${a.name} · ${r?.name}`);save()}
function researcherDecline(form){
  const data=new FormData(form),a=state.applications.find(x=>x.id===data.get('appId'));
  if(!a||a.status!=='researcher_pending'||a.assignedResearcherId!==ui.actor)throw Error('這筆場次目前沒有分派給此研究者。');
  const reason=String(data.get('reason')||'').trim(),detail=String(data.get('detail')||'').trim(),old=a.assignedResearcherId;
  if(!reason||detail.length<3)throw Error('請選擇原因類別並填寫具體理由。');
  a.declineHistory??=[];
  a.declineHistory.push({id:id('decline'),researcherId:old,slotId:a.slotId,slotLabel:slotLabel(slotOf(a)),reason,detail,at:new Date().toISOString()});
  a.declinedResearcherIds=[...new Set([...(a.declinedResearcherIds||[]),old])];a.coordinationAssignment=false;
  assignNextResearcher(a);
  mail('研究者無法執行通知','管理者測試信箱',`${a.name} · ${researcher(old)?.name}：${reason}${detail?`；${detail}`:''}`,{appId:a.id,templateVars:{researcherName:researcher(old)?.name||'研究者',reason,detail}});
  audit('研究者無法收實驗',`${a.name} · ${researcher(old)?.name} · ${reason} · ${detail}`);
  save();
}
function requestReconsider(form){
  const data=new FormData(form),a=state.applications.find(x=>x.id===data.get('appId')),rid=String(data.get('researcherId')||''),message=String(data.get('message')||'').trim();
  const entry=a&&declineHistory(a).slice().reverse().find(x=>x.researcherId===rid&&x.slotId===a.slotId);
  if(!a||!entry||!canRequestReconsider(a,entry))throw Error('此場次目前無法重新指派給該研究者。');
  if(!message)throw Error('請填寫給研究者的訊息。');
  const previous=a.assignedResearcherId;
  if(previous&&previous!==rid)mail('確認請求撤回',researcher(previous)?.name||'研究者',`${a.name} · 此場次改由 ${researcher(rid)?.name||'原研究者'} 再確認`,{appId:a.id,recipientName:researcher(previous)?.name||'研究者',templateVars:{replacementName:researcher(rid)?.name||'原研究者'}});
  a.assignedResearcherId=rid;
  a.coordinationAssignment=false;
  a.status='researcher_pending';
  a.declinedResearcherIds=(a.declinedResearcherIds||[]).filter(x=>x!==rid);
  a.reconsiderationRequests??=[];
  a.reconsiderationRequests.push({id:id('request'),researcherId:rid,slotId:a.slotId,message,at:new Date().toISOString()});
  sendResearcherConfirmation(a,rid,'原時段再次確認邀請',message);
  audit('管理者請研究者再次確認',`${a.name} → ${researcher(rid)?.name} · ${message}`);
  save();
}
function rejectApplication(form){const data=new FormData(form),a=state.applications.find(x=>x.id===data.get('appId'));if(!a)throw Error('找不到案件。');const reason=String(data.get('reason'));a.status='rejected';a.rejectReason=reason;state.outbox=state.outbox.filter(x=>!(x.appId===a.id&&x.kind==='實驗前提醒（預定）'));mail('報名結果通知',a.email,`${a.name} · ${reason}；可查看其他開放時段`,{appId:a.id,recipientName:a.name,templateVars:{reason}});audit('未錄取或請改期',`${a.name} · ${reason} · ${data.get('detail')||''}`);save()}
function coordinate(form){const data=new FormData(form),a=state.applications.find(x=>x.id===data.get('appId')),rid=data.get('researcherId');if(!a||!rid||!state.researchers.some(r=>r.id===rid)||rid===a.assignedResearcherId)throw Error('請選擇一位其他研究者。');a.assignedResearcherId=rid;a.status='researcher_pending';a.coordinationAssignment=true;a.declinedResearcherIds=(a.declinedResearcherIds||[]).filter(x=>x!==rid);sendResearcherConfirmation(a,rid,'支援確認請求');audit('請研究者支援',`${a.name} → ${researcher(rid).name}`);save()}
function reschedule(form){const data=new FormData(form),a=state.applications.find(x=>x.id===data.get('appId')),s=state.slots.find(x=>x.id===data.get('slotId'));if(!a||!s||!isOpen(s))throw Error('新時段已不可選擇。');const old=slotOf(a),oldResearcher=researcher(a.assignedResearcherId),oldSlot=old?`${fmtDateLong(old.date)} ${old.start}–${old.end}`:'原場次',newSlot=`${fmtDateLong(s.date)} ${s.start}–${s.end}`;a.slotId=s.id;a.status='researcher_pending';a.assignedResearcherId=null;a.coordinationAssignment=false;a.declinedResearcherIds=[];state.calendarEvents=state.calendarEvents.filter(x=>x.appId!==a.id);state.outbox=state.outbox.filter(x=>!(x.appId===a.id&&x.kind==='實驗前提醒（預定）'));if(oldResearcher)mail('研究者原行程取消通知',oldResearcher.email,`${a.name} · 原場次 ${slotLabel(old)} 已取消`,{appId:a.id,recipientName:oldResearcher.name,templateVars:{oldSlot,newSlot}});assignNextResearcher(a);mail('改期處理中',a.email,`${a.name} · 原時段 ${slotLabel(old)} 已變更，新時段待研究者確認`,{appId:a.id,recipientName:a.name,templateVars:{oldSlot,newSlot}});audit('改期',`${a.name} · ${slotLabel(old)} → ${slotLabel(s)}`);save()}
function saveSession(form){const data=new FormData(form),a=state.applications.find(x=>x.id===data.get('appId'));if(!canRecord(a))throw Error('只能紀錄自己的實驗場次。');const attendance=data.get('attendance');if(!attendance)throw Error('請選擇出席狀況。');const blacklisted=data.has('blacklisted'),reason=String(data.get('blacklistReason')||'').trim();if(blacklisted&&!reason)throw Error('標記再次報名需審核時，請填原因。');a.attendance=attendance;a.status=attendance==='no_show'?'no_show':'completed';a.resultRequested=data.has('resultRequested');a.blacklisted=blacklisted;a.blacklistReason=blacklisted?reason:'';a.participantNote=String(data.get('participantNote')||'').trim();audit('場次紀錄',`${a.name} · ${attendance}`);save()}
function saveOverallNote(form){const data=new FormData(form),text=String(data.get('text')||'').trim();if(!text)throw Error('請輸入觀察內容。');state.overallNotes.unshift({id:id('note'),date:data.get('date'),researcherId:isAdmin()?null:ui.actor,researcherName:actorName(),text});audit('整體觀察札記',`${data.get('date')} · ${text.slice(0,28)}`);save()}
function addResearcher(form){const data=new FormData(form),name=String(data.get('name')).trim(),email=String(data.get('email')).trim(),color=String(data.get('color'));if(!name||!email)throw Error('請填研究者名稱與代號信箱。');if(state.researchers.some(r=>r.email.toLowerCase()===email.toLowerCase()))throw Error('這個 email 已經有研究者使用。');state.researchers.push({id:id('r'),name,email,color});audit('新增研究者',name);save()}
function saveResearcherEmail(form){const data=new FormData(form),r=researcher(String(data.get('researcherId'))),email=String(data.get('email')||'').trim();if(!r||!email)throw Error('請輸入有效 email。');if(state.researchers.some(x=>x.id!==r.id&&x.email.toLowerCase()===email.toLowerCase()))throw Error('這個 email 已經有研究者使用。');r.email=email;audit('更新研究者信箱',`${r.name} · ${email}`);save()}
function sendAvailabilityReminders(month,{scheduled=false}={}){
  if(!isAdmin())return notify('只有管理者能寄送團隊提醒。');
  ensureMonth(month);
  const missing=state.researchers.filter(r=>!state.slots.some(s=>s.date.startsWith(month)&&s.researcherIds.includes(r.id)));
  if(!missing.length){if(scheduled)state.mailSettings.lastReminderMonth=month;save();return notify(`${month} 的研究者都已至少填寫一個可收時段。`)}
  for(const r of missing){const token=id('availability'),actionUrl=localActionUrl({availability:month,researcher:r.id,key:token});mail('研究者排班提醒',r.email,`${month} 可收時間尚待填寫`,{recipientName:r.name,researcherId:r.id,linkType:'availability',actionToken:token,month,actionUrl})}
  if(scheduled)state.mailSettings.lastReminderMonth=month;
  audit(scheduled?'自動排班提醒（模擬）':'立即排班提醒（模擬）',`${month} · ${missing.map(r=>r.name).join('、')}`);save();notify(`已為 ${missing.length} 位尚未填時段的研究者建立測試提醒。`)
}
function runDueMonthlyReminder(){const settings=state.mailSettings,month=monthKey(today);if(!settings?.monthlyAvailabilityReminderEnabled||settings.lastReminderMonth===month||today.getDate()<Number(settings.reminderDay||1))return;sendAvailabilityReminders(month,{scheduled:true})}
function simulateCalendarSync(){if(!isAdmin())return notify('只有管理者能操作團隊日曆。');const pending=state.calendarEvents.filter(e=>e.syncStatus!=='synced');if(!pending.length)return notify('沒有待同步行程。');for(const e of pending){e.syncStatus='synced';e.lastSyncedAt=new Date().toISOString()}audit('模擬同步 Google 日曆',`${pending.length} 筆`);save();notify(`已標記 ${pending.length} 筆為模擬同步；尚未寫入 Google。`)}
function icsEscape(value){return String(value||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function icsUtc(date,time){const [year,month,day]=date.split('-').map(Number),[hour,minute]=time.split(':').map(Number);return new Date(Date.UTC(year,month-1,day,hour-8,minute)).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}
function exportCalendarIcs(){const events=state.calendarEvents.filter(e=>{const a=state.applications.find(x=>x.id===e.appId);return a&&['confirmed','completed','no_show'].includes(a.status)&&(isAdmin()||e.researcherId===ui.actor)});if(!events.length)return notify('目前沒有可匯出的已確認場次。');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Movement Thought Study//Research Desk','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const e of events){const a=state.applications.find(x=>x.id===e.appId),s=state.slots.find(x=>x.id===e.slotId);if(!a||!s)continue;lines.push('BEGIN:VEVENT',`UID:${e.id}@movement-thought.local`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}`,`DTSTART:${icsUtc(s.date,s.start)}`,`DTEND:${icsUtc(s.date,s.end)}`,`SUMMARY:${icsEscape(`動作與思考研究｜${a.name}`)}`,`DESCRIPTION:${icsEscape(`${researcher(e.researcherId)?.name||'研究者'} · 受試者姓名 ${a.name}`)}`,`LOCATION:${icsEscape('國立臺灣科技大學國際大樓12樓 IB-1214 教室')}`,'END:VEVENT')}lines.push('END:VCALENDAR');const blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='movement-thought-study.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);notify(`已匯出 ${events.length} 筆行程；可手動匯入 Google 日曆。`)}
function handleActionLink(){
  const url=new URL(location.href),confirmId=url.searchParams.get('confirm'),rid=url.searchParams.get('researcher'),key=url.searchParams.get('key'),month=url.searchParams.get('availability');
  if(confirmId){const a=state.applications.find(x=>x.id===confirmId),valid=a&&a.status==='researcher_pending'&&a.assignedResearcherId===rid&&a.researcherConfirmationToken===key;if(valid){ui.actor=rid;ui.view='workflow';ui.filter='all';const s=slotOf(a);if(s){ui.month=s.date.slice(0,7);ui.day=s.date}render();openResearcherConfirm(a)}else{if(researcher(rid))ui.actor=rid;ui.view='workflow';ui.filter='all';render();notify('這封確認信已失效或案件已更新，請聯絡管理者。')}history.replaceState(null,'',url.pathname)}
  else if(month){const reminder=state.outbox.find(x=>x.linkType==='availability'&&x.month===month&&x.researcherId===rid&&x.actionToken===key);if(reminder&&researcher(rid)){ui.actor=rid;ui.view='availability';ui.filter='all';ui.month=month;ui.day=`${month}-01`;while(isWeekend(ui.day))ui.day=addDays(ui.day,1);ensureMonth(month);render();openMyDayEditor(ui.day)}else{notify('這封排班提醒連結已失效，請向管理者索取最新連結。')}history.replaceState(null,'',url.pathname)}
}
function exportJson(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='movement-study-demo.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已下載本機虛構測試資料。')}

runDueMonthlyReminder();
render();
handleActionLink();
